-- GENERATED by `pnpm db:export` from src/store. Do not edit; add a new migration in src/store/migrations.ts.
-- Usage: psql "$DATABASE_MIGRATION_URL" -X -v ON_ERROR_STOP=1 -1 -f db/seed/dev-seed.sql

DO $guard$
BEGIN
  IF current_database() !~ '^workday_mcp_(dev|test|check)(_[a-z0-9]+)?$' THEN
    RAISE EXCEPTION 'dev seed refused: database % is not on the dev allowlist (^workday_mcp_(dev|test|check)(_[a-z0-9]+)?$)', current_database();
  END IF;
  IF to_regclass('schema_migrations') IS NULL OR (SELECT max(version) FROM schema_migrations) IS NULL THEN
    RAISE EXCEPTION 'dev seed refused: run migrations first';
  END IF;
  IF EXISTS (SELECT 1 FROM oauth_tokens) THEN
    RAISE EXCEPTION 'dev seed refused: database holds OAuth tokens (looks like real use)';
  END IF;
END
$guard$;

